const body = $input.first().json.body || $input.first().json;

// Extract client info
const name = body.name || body.customer_name || 'Cliente VIP';
const email = body.email || body.customer_email || 'cliente@email.com';
const daysValid = Number(body.days || body.plan_days || 30);

// Generate username and password
const randomNum = Math.floor(1000 + Math.random() * 9000);
const cleanName = (name.split(' ')[0] || 'vip').toLowerCase().replace(/[^a-z0-9]/g, '');
const username = body.username || `${cleanName}_${randomNum}`;
const password = body.password || `play_${Math.random().toString(36).substring(2, 8)}`;

return {
  json: {
    name,
    email,
    username,
    password,
    daysValid,
    phone: body.phone || body.customer_phone || ''
  }
};

const res = $input.first().json;
const creds = res.loginCredentials || {};
const user = res.user || {};

const whatsappMessage = `
🌟 *Seu Acesso ao M3U PLAY Está Liberado!*
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Olá, *${user.name}*!

Seu painel de reprodução exclusivo foi criado com sucesso:

🌐 *Acesso Web:* ${creds.loginUrl}
👤 *Usuário:* \`${creds.username}\`
🔑 *Senha:* \`${creds.password}\`
📅 *Validade do Acesso:* ${new Date(user.expiresAt).toLocaleDateString('pt-BR')} (${user.daysValid} dias)

📺 *Dica:* Você pode assistir no celular, computador ou diretamente no navegador da sua Smart TV!
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
_Bom entretenimento!_
`;

return {
  json: {
    success: true,
    user,
    loginCredentials: creds,
    formattedMessage: whatsappMessage
  }
};
